import csv
import io
import re
from typing import List, Dict, Any

def parse_csv(raw_csv: str):
    reader = csv.reader(
        io.StringIO(raw_csv),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False
    )
    parsed = []
    try:
        for row in reader:
            parsed.append([str(value) for value in row])
    except Exception:
        pass

    nonempty = [
        (index, row)
        for index, row in enumerate(parsed)
        if any(str(value).strip() for value in row)
    ]

    if not nonempty:
        return {"columns": [], "rows": []}

    date_pattern = re.compile(
        r"^\s*\d{1,4}\s*[/.-]\s*\d{1,2}\s*[/.-]\s*\d{1,4}\s*$"
    )
    time_pattern = re.compile(r"^\s*\d{1,2}\s*:\s*\d{2}(?:\s*:\s*\d{2})?\s*$")

    data_index = None
    for index, row in nonempty:
        if len(row) >= 2 and date_pattern.match(row[0]) and time_pattern.match(row[1]):
            data_index = index
            break

    if data_index is not None:
        header_index = None
        for index, row in reversed(nonempty):
            if index < data_index and len(row) > 1:
                header_index = index
                break
        if header_index is None:
            header_index = nonempty[0][0]
    else:
        header_index = nonempty[0][0]

    columns = list(parsed[header_index])
    if not columns:
        return {"columns": [], "rows": []}

    width = len(columns)
    url_pattern = re.compile(r"^[a-zA-Z][a-zA-Z0-9+.-]*://")

    def looks_like_description(value: str) -> bool:
        text = value.strip()
        if len(text) >= 30:
            return True
        words = re.findall(r"[A-Za-z]+(?:['-][A-Za-z]+)?", text)
        if len(words) >= 3:
            lower_words = sum(1 for word in words[1:] if word[:1].islower())
            if lower_words >= 2:
                return True
        return False

    def repair_row(row: List[str]) -> List[str]:
        values = list(row)

        url_index = None
        for index, value in enumerate(values):
            if url_pattern.match(value.strip()):
                url_index = index
                break

        if url_index is not None and width >= 8 and url_index >= 6:
            prefix = values[:url_index]
            suffix = values[url_index + 1:]

            if len(prefix) >= 7:
                product_parts = prefix[5:]
                if len(product_parts) == 2:
                    product_type = product_parts[0]
                    description = product_parts[1]
                elif len(product_parts) > 2:
                    boundary = None
                    for candidate in range(1, len(product_parts)):
                        if looks_like_description(product_parts[candidate]):
                            boundary = candidate
                            break
                    if boundary is None:
                        boundary = 1
                    product_type = ",".join(product_parts[:boundary])
                    description = ",".join(product_parts[boundary:])
                else:
                    product_type = product_parts[0] if product_parts else ""
                    description = ""
                rebuilt = prefix[:5] + [product_type, description, values[url_index]]
                rebuilt.append(",".join(suffix))
                values = rebuilt

        if len(values) < width:
            values.extend([""] * (width - len(values)))
        elif len(values) > width:
            values = values[:width - 1] + [",".join(values[width - 1:])]

        return [str(value) for value in values]

    rows = []
    for index, row in enumerate(parsed):
        if index <= header_index:
            continue
        if not row or not any(str(value).strip() for value in row):
            continue
        rows.append(repair_row(row))

    return {"columns": [str(value) for value in columns], "rows": rows}
